def transform(grid):
    h, w = len(grid), len(grid[0])

    # Identify full-width and full-height separator lines.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def regions(size, separators):
        bounds = [-1] + separators + [size]
        return [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)]

    rr = regions(h, sep_rows)
    cc = regions(w, sep_cols)
    out = [row[:] for row in grid]

    # Find the region containing the pattern, identified by non-background
    # cells other than the separator color.
    sep_color = grid[sep_rows[0]][0] if sep_rows else (
        grid[0][sep_cols[0]] if sep_cols else None
    )
    background = None
    for r0, r1 in rr:
        for c0, c1 in cc:
            vals = [grid[r][c] for r in range(r0, r1) for c in range(c0, c1)]
            counts = {}
            for v in vals:
                counts[v] = counts.get(v, 0) + 1
            if vals:
                background = max(counts, key=counts.get)
                break
        if background is not None:
            break

    source = None
    for r0, r1 in rr:
        for c0, c1 in cc:
            if any(grid[r][c] != background for r in range(r0, r1) for c in range(c0, c1)):
                source = (r0, r1, c0, c1)
                break
        if source:
            break

    if source is None:
        return out

    r0, r1, c0, c1 = source
    pattern = [grid[r][c0:c1] for r in range(r0, r1)]
    for a, b in rr:
        for x, y in cc:
            if (a, b, x, y) == source:
                continue
            for i, r in enumerate(range(a, b)):
                for j, c in enumerate(range(x, y)):
                    out[r][c] = pattern[i % len(pattern)][j % len(pattern[0])]
    return out
