def transform(grid):
    h, w = len(grid), len(grid[0])

    # Uniform separator lines use the same separator color.
    uniform_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_color = grid[uniform_rows[0]][0] if uniform_rows else None
    sep_rows = [r for r in uniform_rows if grid[r][0] == sep_color]
    sep_cols = [
        c for c in range(w)
        if sep_color is not None and all(grid[r][c] == sep_color for r in range(h))
    ]

    def intervals(n, cuts):
        starts = [0] + [x + 1 for x in cuts]
        ends = cuts + [n]
        return list(zip(starts, ends))

    row_regions = intervals(h, sep_rows)
    col_regions = intervals(w, sep_cols)
    out = [row[:] for row in grid]

    # The most frequent non-separator color is the empty background.
    counts = {}
    for row in grid:
        for value in row:
            if value != sep_color:
                counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    source = None
    for r0, r1 in row_regions:
        for c0, c1 in col_regions:
            if any(grid[r][c] != background
                   for r in range(r0, r1) for c in range(c0, c1)):
                source = (r0, r1, c0, c1)
                break
        if source:
            break

    if source is None:
        return out

    r0, r1, c0, c1 = source
    pattern = [grid[r][c0:c1] for r in range(r0, r1)]
    for a, b in row_regions:
        for x, y in col_regions:
            if (a, b, x, y) == source:
                continue
            for r in range(a, b):
                for c in range(x, y):
                    out[r][c] = pattern[(r - a) % len(pattern)][(c - x) % len(pattern[0])]
    return out
